param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$ExpectedSid)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$out=Join-Path $Root 'results';$report=@{status='running';named_fields=@();scope='Exact installed Windows Settings native navigation role/action/selected state and coherent Create/Rename field geometry; source and preference preservation';cases=@()};$final='failed native main field audit';$owned=[Collections.Generic.List[Diagnostics.Process]]::new();$forms=[Collections.Generic.List[object]]::new();$install=$null
function Require($value,$message){if(-not$value){throw $message}}
function Save{$p=Join-Path $out 'RESULT.json';$tmp=$p+'.next';[IO.File]::WriteAllText($tmp,($report|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));if(Test-Path $p){[IO.File]::Replace($tmp,$p,[NullString]::Value)}else{[IO.File]::Move($tmp,$p)}}
function Phase($value){$report.phase=$value;Save}
function Run($exe,$arguments,$name){
 $s=[Diagnostics.ProcessStartInfo]::new($exe,$arguments);$s.UseShellExecute=$false;$s.CreateNoWindow=$true;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true;$s.StandardOutputEncoding=[Text.UTF8Encoding]::new($false);$s.StandardErrorEncoding=[Text.UTF8Encoding]::new($false);$clock=[Diagnostics.Stopwatch]::StartNew();$p=[Diagnostics.Process]::Start($s)
 try{
  $stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync()
  if(-not$p.WaitForExit(180000)){
   $snapshot=@(Get-CimInstance Win32_Process|Where-Object {$_.ProcessId-eq$p.Id-or$_.ParentProcessId-eq$p.Id-or($install-and$_.ExecutablePath-and$_.ExecutablePath.StartsWith($install,[StringComparison]::OrdinalIgnoreCase))}|Select-Object Name,ProcessId,ParentProcessId,ExecutablePath,SessionId)
   [IO.File]::WriteAllText((Join-Path $out ($name+'-timeout.json')),(@{seconds=$clock.Elapsed.TotalSeconds;root_pid=$p.Id;processes=$snapshot}|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));throw ('Owned process timeout '+$name)
  }
  Require ($stdout.Wait(5000)-and$stderr.Wait(5000)) 'Process streams not complete';$v=@{exit=$p.ExitCode;stdout=$stdout.Result;stderr=$stderr.Result;seconds=$clock.Elapsed.TotalSeconds};[IO.File]::WriteAllText((Join-Path $out ($name+'-process.json')),($v|ConvertTo-Json),[Text.UTF8Encoding]::new($false));Require ($v.exit-eq0) ('Native child failed '+$name);return $v
 }finally{if(-not$p.HasExited){& "$env:SystemRoot\System32\taskkill.exe" /PID $p.Id /T /F|Out-Null;$null=$p.WaitForExit(10000)};$p.Dispose()}
}
& ([ScriptBlock]::Create([IO.File]::ReadAllText((Join-Path $Root 'native-controls.ps1'))));[PickerNative]::Init()
Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes
function Pump{[Windows.Forms.Application]::DoEvents();Start-Sleep -Milliseconds 50}
function Tree($w){return [Windows.Automation.AutomationElement]::FromHandle($w)}
function Nodes($w,$name){$c=[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,$name);return @((Tree $w).FindAll([Windows.Automation.TreeScope]::Descendants,$c)|Where-Object {-not$_.Current.IsOffscreen})}
function Node($w,$name,$kind){$deadline=[DateTime]::UtcNow.AddSeconds(20);do{$n=@(Nodes $w $name|Where-Object {$_.Current.ControlType-eq$kind});if($n.Count-eq1){return $n[0]};Pump}while([DateTime]::UtcNow-lt$deadline);[PickerNative]::Shot($w,(Join-Path $out 'missing-control.png'));throw ('Missing unique '+$name+' count='+$n.Count)}
function Invoke($w,$name){$n=Node $w $name ([Windows.Automation.ControlType]::Button);$n.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();Pump}
function Key($w,$key){[PickerNative]::Focus($w);[Windows.Forms.SendKeys]::SendWait($key);Start-Sleep -Milliseconds 300;Pump}
function Field($w,$name){$n=Node $w $name ([Windows.Automation.ControlType]::Edit);$v=$n.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current;return @{name=$n.Current.Name;value=$v.Value;read_only=$v.IsReadOnly;role='Edit';height=$n.Current.BoundingRectangle.Height;width=$n.Current.BoundingRectangle.Width}}
try{
 Require ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value-eq$ExpectedSid) 'Wrong owned account';Require (-not([Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) 'Ordinary token required'
 $identity=Get-Content (Join-Path $Root 'application-input.json') -Raw|ConvertFrom-Json;foreach($file in $identity.files){Require ((Get-FileHash (Join-Path $Root $file.name)).Hash.ToLowerInvariant()-eq$file.sha256) 'Native actor input mismatch'};$report.package=$identity
 $manifest=Get-Content (Join-Path $Root 'payload.json') -Raw|ConvertFrom-Json;$install=Join-Path $env:LOCALAPPDATA 'Programs\Ottrin';$app=Join-Path $install 'bin\ottrin.exe';Require (-not(Test-Path $install)) 'Existing installation retained'
 Phase 'install exact staged NSIS';$null=Run (Join-Path $Root 'current-setup.exe') '/S' 'install'
 foreach($file in $manifest.PSObject.Properties){Require ((Get-FileHash (Join-Path $install $file.Name)).Hash.ToLowerInvariant()-eq$file.Value) ('Payload mismatch '+$file.Name)}
 $null=Run $app 'index service-remove' 'index-remove';Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Owned index process remains'
 $corpus=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'OttrinFields';Require (-not(Test-Path $corpus)) 'Existing corpus retained';$null=[IO.Directory]::CreateDirectory($corpus);$source=Join-Path $corpus 'preserve.txt';[IO.File]::WriteAllText($source,'owned original',[Text.UTF8Encoding]::new($false));$sourceHash=(Get-FileHash $source).Hash
 $config=Get-Content (Join-Path $Root 'config-template.json') -Raw|ConvertFrom-Json;$config.bookmarks=@();$config.default_view_mode='List';$config.graphics_renderer='Native';$config.search.include_roots=@($corpus);$config.search.content_indexing_enabled=$false;$pref=Join-Path $env:APPDATA 'ottrin\config.json';Require (-not(Test-Path $pref)) 'Existing config retained';$null=[IO.Directory]::CreateDirectory((Split-Path $pref))
 foreach($theme in @('Dark','Light')){
  Phase ($theme+' main fields');$config.theme=$theme;[IO.File]::WriteAllText($pref,($config|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))
  $s=[Diagnostics.ProcessStartInfo]::new($app,('"'+$corpus+'"'));$s.UseShellExecute=$false;$p=[Diagnostics.Process]::Start($s);$owned.Add($p);$deadline=[DateTime]::UtcNow.AddSeconds(25)
  do{$w=[PickerNative]::Window($p.Id,'Ottrin');if($w-ne[IntPtr]::Zero){break};Pump}while([DateTime]::UtcNow-lt$deadline);Require ($w-ne[IntPtr]::Zero) 'No owned main window';[PickerNative]::Focus($w)
  $creationHeights=@();foreach($kind in @('File','Folder')){
   Invoke $w 'Menu';Invoke $w ('New '+$kind);$name=$kind+' name';$f=Field $w $name;$creationHeights+=@($f.height);Require ($f.value-eq''-and-not$f.read_only) 'Wrong creation role/value';Key $w ('draft-'+$kind.ToLowerInvariant());$typed=Field $w $name;Require ($typed.value-eq('draft-'+$kind.ToLowerInvariant())) 'Typing did not reach named field';[PickerNative]::Shot($w,(Join-Path $out ($theme+'-'+$kind+'.png')));Invoke $w 'Cancel';Require (-not(Test-Path (Join-Path $corpus $typed.value))) 'Cancel created output';$report.cases+=@{theme=$theme;case='creation-'+$kind;initial=$f;typed=$typed;cancel_preserved_source=$true};Save
  }
  $entry=Node $w 'preserve.txt' ([Windows.Automation.ControlType]::Button);$supported=@($entry.GetSupportedPatterns());$entryPatterns=@($supported|ForEach-Object {$_.ProgrammaticName});$report.file_entry_patterns=@{theme=$theme;name=$entry.Current.Name;patterns=$entryPatterns};Save;Require (@($supported|Where-Object {$_.Id-eq([Windows.Automation.TogglePattern]::Pattern).Id}).Count-eq1) 'File selection row has no native Toggle pattern';$toggle=$entry.GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern);if($toggle.Current.ToggleState-ne[Windows.Automation.ToggleState]::On){$toggle.Toggle()};$selectionClock=[Diagnostics.Stopwatch]::StartNew();$deadline=[DateTime]::UtcNow.AddSeconds(10);$selectionStates=@();do{$toggle=(Node $w 'preserve.txt' ([Windows.Automation.ControlType]::Button)).GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern);$state=$toggle.Current.ToggleState.ToString();if($state-notin$selectionStates){$selectionStates+=@($state)};if($state-eq'On'){break};Pump}while([DateTime]::UtcNow-lt$deadline);$report.selection_probe=@{theme=$theme;states=$selectionStates;elapsed_ms=$selectionClock.Elapsed.TotalMilliseconds};Save;if($state-ne'On'){[PickerNative]::Shot($w,(Join-Path $out 'selection-did-not-change.png'))};Require ($state-eq'On') 'Native file row did not become selected within10 seconds';(Node $w 'preserve.txt' ([Windows.Automation.ControlType]::Button)).SetFocus();$deadline=[DateTime]::UtcNow.AddSeconds(10);do{$row=Node $w 'preserve.txt' ([Windows.Automation.ControlType]::Button);if($row.Current.HasKeyboardFocus){break};Pump}while([DateTime]::UtcNow-lt$deadline);Require $row.Current.HasKeyboardFocus 'Native file row did not receive keyboard focus';$focused=[Windows.Automation.AutomationElement]::FocusedElement;$report.focus_before_f2=@{owned=($focused-and$focused.Current.ProcessId-eq$p.Id)};if($report.focus_before_f2.owned){$report.focus_before_f2.name=$focused.Current.Name;$report.focus_before_f2.control_type=$focused.Current.ControlType.ProgrammaticName;$report.focus_before_f2.has_keyboard_focus=$focused.Current.HasKeyboardFocus};Save;Key $w '{F2}';$rename=Field $w 'New name';Require ($rename.value-eq'preserve.txt'-and-not$rename.read_only) 'Wrong actual rename value';Require (@($creationHeights|Where-Object {[Math]::Abs($_-$rename.height)-gt1}).Count-eq0) 'Creation and Rename native field heights differ';Key $w '^a';Key $w 'cancelled-rename.txt';$typedRename=Field $w 'New name';Require ($typedRename.value-eq'cancelled-rename.txt') 'Rename did not accept typed value';[PickerNative]::Shot($w,(Join-Path $out ($theme+'-Rename.png')));Invoke $w 'Cancel';Require ((Get-FileHash $source).Hash-eq$sourceHash-and-not(Test-Path (Join-Path $corpus 'cancelled-rename.txt'))) 'Rename cancel changed source';$report.cases+=@{theme=$theme;case='rename-geometry-and-cancel';creation_heights=$creationHeights;field=$rename;typed=$typedRename};Save
  Invoke $w 'Menu';Invoke $w ('Settings'+[char]0x2026);$deadline=[DateTime]::UtcNow.AddSeconds(20);do{$settings=[PickerNative]::Window($p.Id,'Ottrin Settings');if($settings-ne[IntPtr]::Zero){break};Pump}while([DateTime]::UtcNow-lt$deadline);Require ($settings-ne[IntPtr]::Zero) 'No actual Settings window';[PickerNative]::Place($settings)
  $navNames=@('General','Appearance','Files','Services','Search','Cache');foreach($label in $navNames){$null=Node $settings $label ([Windows.Automation.ControlType]::RadioButton)}
  foreach($label in @('Services','Appearance','Files','Search','Cache','General')){
   $radio=Node $settings $label ([Windows.Automation.ControlType]::RadioButton);$radio.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();$deadline=[DateTime]::UtcNow.AddSeconds(10)
   do{$checked=@($navNames|Where-Object {(Node $settings $_ ([Windows.Automation.ControlType]::RadioButton)).GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Current.IsSelected});if($checked.Count-eq1-and$checked[0]-eq$label){break};Pump}while([DateTime]::UtcNow-lt$deadline)
   Require ($checked.Count-eq1-and$checked[0]-eq$label) ('Wrong selected navigation choice '+$label);$report.cases+=@{theme=$theme;case='native-navigation';label=$label;role='RadioButton';native_action='SelectionItem.Select';only_selected=$checked};if($label-eq'Services'){[PickerNative]::Shot($settings,(Join-Path $out ($theme+'-Settings-Services.png')))};Save
  }
  Invoke $settings 'Close window';$deadline=[DateTime]::UtcNow.AddSeconds(10);while([PickerNative]::Window($p.Id,'Ottrin Settings')-ne[IntPtr]::Zero){Require ([DateTime]::UtcNow-lt$deadline) 'Settings native Close did not finish';Pump}
  Key $w '^l';$f=Field $w 'Location';$expectedNative='\\?\'+$corpus;$report.location_observed=@{field=$f;expected=$expectedNative};Save;Require ($f.value-ceq$expectedNative) ('Location value mismatch: '+$f.value);$report.cases+=@{theme=$theme;case='location';field=$f;expected_native_path=$expectedNative};Key $w '{ESC}'
  Key $w '^f';$f=Field $w 'Search files and folders';Require (-not$f.read_only) 'Search unexpectedly read-only';$report.cases+=@{theme=$theme;case='search';field=$f};Key $w '{ESC}';Invoke $w 'Close window';Require ($p.WaitForExit(15000)-and$p.ExitCode-eq0) 'Normal native close failed';Require ((Get-FileHash $source).Hash-eq$sourceHash) 'Source changed';Save
 }
 $saved=(Get-FileHash $pref).Hash;Phase 'supported uninstall';$uninstaller=Join-Path $out 'owned-uninstall.exe';Copy-Item (Join-Path $install 'Uninstall.exe') $uninstaller;$null=Run $uninstaller ('/S _?='+$install) 'uninstall';Remove-Item $uninstaller;Require (-not(Test-Path $install)) 'Installation remains';Require ((Get-FileHash $pref).Hash-eq$saved) 'Uninstall changed preferences';Require ((Get-FileHash $source).Hash-eq$sourceHash) 'Source changed';$report.preferences_preserved=$true;$report.source_preserved=$true;$final='pass native installed navigation and filename geometry scope; captures require review'
}catch{$report.error=$_.Exception.Message;$report.stack=$_.ScriptStackTrace}
finally{
 foreach($p in $owned){if(-not$p.HasExited){& "$env:SystemRoot\System32\taskkill.exe" /PID $p.Id /T /F|Out-Null;$null=$p.WaitForExit(10000)}}
 if($install-and(Test-Path $app)-and$manifest-and(Get-FileHash $app).Hash.ToLowerInvariant()-eq$manifest.'bin/ottrin.exe'){try{$report.cleanup_index_remove=Run $app 'index service-remove' 'cleanup-index-remove'}catch{$report.cleanup_index_error=$_.Exception.Message;$final='failed owned index teardown'}}
 if($install){$left=@(Get-CimInstance Win32_Process|Where-Object {$_.ExecutablePath-and$_.ExecutablePath.StartsWith($install,[StringComparison]::OrdinalIgnoreCase)});$report.remaining_owned_installed_processes=$left.Count;if($left.Count){$final='failed owned process teardown'}}
 $report.status=$final;Save
}
if(-not$final.StartsWith('pass')){exit 1}
